func parseOptions(args []string) (Object, error) {
	o := Object{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "--") {
			return nil, fmt.Errorf("unexpected positional argument %s", arg)
		}
		key := strings.ReplaceAll(strings.TrimPrefix(arg, "--"), "-", "_")
		if _, exists := o[key]; exists {
			return nil, fmt.Errorf("repeated option %s", arg)
		}
		if key == "retain_evidence" {
			o[key] = true
			continue
		}
		i++
		if i >= len(args) {
			return nil, fmt.Errorf("%s requires a value", arg)
		}
		value := args[i]
		if strings.HasSuffix(key, "_bytes") || key == "database_pid" {
			n, e := strconv.ParseInt(value, 10, 64)
			if e != nil {
				return nil, fmt.Errorf("%s must be signed integer", arg)
			}
			o[key] = n
		} else {
			o[key] = value
		}
	}
	return o, nil
}

func Run(ctx context.Context, args []string, out io.Writer) (err error) {
	defer recoverError(&err)
	if len(args) == 0 {
		return fmt.Errorf("runtime-priority requires qualify, pressure, probe-admission, adapter, or remote")
	}
	command := args[0]
	args = args[1:]
	switch command {

case "pressure":
	if len(args) == 0 {
		return fmt.Errorf("pressure requires dry-run, run, or stress-worker")
	}
	mode := args[0]
	args = args[1:]
	if mode == "resource-worker" {
		return RunResourceWorker(ctx, args, out)
	}
	options, e := parseOptions(args)
	if e != nil {
		return e
	}
	manifest, wire, e := LoadJSON(text(options["manifest"], "--manifest"), 1<<20)
	if e != nil {
		return e
	}
	switch mode {
	case "dry-run":
		plan, e := DryRun(manifest, Hash(wire))
		if e != nil {
			return e
		}
		_, e = out.Write(pretty(plan))
		return e
	case "run":
		status, e := RunQualification(ctx, manifest, wire, Hash(wire), text(options["evidence_dir"], "--evidence-dir"), nil, out)
		if e != nil {
			return e
		}
		if status != 0 {
			return fmt.Errorf("runtime priority qualification did not pass")
		}
		return nil
	case "stress-worker":
		assigned := text(options["assigned_pressure_cgroup"], "--assigned-pressure-cgroup")
		if str(sub(sub(manifest, "pressure"), "workload_cgroup"), "path") != assigned {
			return fmt.Errorf("stress worker assigned scope differs from manifest")
		}
		return RunStressWorker(ctx, manifest, text(options["expected_native_runner_cgroup"], "--expected-native-runner-cgroup"), text(options["protected_database_cgroup"], "--protected-database-cgroup"), text(options["run_id"], "--run-id"), options["retain_evidence"] == true, out)
	default:
		return fmt.Errorf("unsupported pressure mode %s", mode)
	}

func inside(path, root string) bool {
	rel, e := filepath.Rel(root, path)
	return e == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, "../")
}
func safePath(path string) bool {
	return filepath.IsAbs(path) && filepath.Clean(path) == path && !strings.Contains(path, "/../")
}
func readNoFollow(path string, maximum int64) ([]byte, os.FileInfo, error) {
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		return nil, nil, e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	before, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	if !before.Mode().IsRegular() || before.Size() > maximum {
		return nil, nil, fmt.Errorf("%s must be a regular file no larger than %d bytes", path, maximum)
	}
	wire, e := io.ReadAll(io.LimitReader(f, maximum+1))
	if e != nil {
		return nil, nil, e
	}
	after, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	named, e := os.Lstat(path)
	if e != nil {
		return nil, nil, e
	}
	if int64(len(wire)) > maximum || !os.SameFile(before, after) || !os.SameFile(before, named) || before.Size() != after.Size() || before.ModTime() != after.ModTime() {
		return nil, nil, fmt.Errorf("%s changed during readback", path)
	}
	return wire, before, nil
}
func LoadJSON(path string, maximum int64) (Object, []byte, error) {
	wire, _, e := readNoFollow(path, maximum)
	if e != nil {
		return nil, nil, e
	}
	var o Object
	e = json.Unmarshal(wire, &o)
	if e != nil {
		return nil, nil, fmt.Errorf("%s invalid JSON: %w", path, e)
	}
	if o == nil {
		return nil, nil, fmt.Errorf("%s must be a JSON object", path)
	}
	return o, wire, nil
}
func load(path string, maximum int64) (Object, []byte) {
	o, b, e := LoadJSON(path, maximum)
	if e != nil {
		fail("%v", e)
	}
	return o, b
}

func ValidateStressWorkerManifest(manifest Object) (err error) {
	defer recoverError(&err)
	if manifest["schema"] != Schema {
		fail("stress manifest schema must be %q", Schema)
	}
	p := sub(manifest, "pressure")
	for _, key := range []string{"duration_seconds", "sample_interval_seconds", "cpu_workers", "memory_bytes", "memory_headroom_bytes", "io_workers", "io_file_bytes", "io_total_bytes", "io_bytes_per_second", "io_block_bytes"} {
		num(p[key], "stress pressure."+key, 1)
	}
	duration, cpus, ios, memory, headroom := n(p, "duration_seconds"), n(p, "cpu_workers"), n(p, "io_workers"), n(p, "memory_bytes"), n(p, "memory_headroom_bytes")
	if duration > 900 {
		fail("stress duration exceeds its harness bound")
	}
	if cpus > 64 || ios > 32 || memory > 16<<30 || headroom > 16<<30-memory {
		fail("stress worker count or memory request exceeds its harness bound")
	}
	file, total, rate, block := n(p, "io_file_bytes"), n(p, "io_total_bytes"), n(p, "io_bytes_per_second"), n(p, "io_block_bytes")
	if file > 2<<30 || file > 4<<30/ios || total > 64<<30 || rate > 128<<20 || total < rate*duration || block&(block-1) != 0 || file%block != 0 {
		fail("stress I/O request exceeds its finite worker bounds")
	}
	w := sub(p, "workload_cgroup")
	if !exact(w, "parent_path", "path", "cpu_max", "memory_max_bytes", "io_weight", "io_device") {
		fail("stress workload cgroup fields do not match the transient-scope contract")
	}
	for _, key := range []string{"parent_path", "path"} {
		value := text(w[key], "stress workload cgroup "+key)
		if !safePath(value) || value == CgroupRoot {
			fail("stress workload cgroup %s is not a safe cgroup path", key)
		}
	}
	fields := strings.Fields(str(w, "cpu_max"))
	if len(fields) != 2 || !decimalRE.MatchString(fields[0]) || !decimalRE.MatchString(fields[1]) || integerText(fields[0], "cpu.max") <= 0 || fields[1] != "100000" {
		fail("stress workload cpu_max must have an explicit finite 100000 period")
	}
	cap := num(w["memory_max_bytes"], "stress workload memory_max_bytes", 1)
	num(w["io_weight"], "stress workload io_weight", 1)
	if !blockDeviceRE.MatchString(str(w, "io_device")) {
		fail("stress workload I/O device must be a block device")
	}
	if memory > cap || headroom > cap-memory {
		fail("stress memory request exceeds its transient-scope memory.max")
	}
	if !filepath.IsAbs(str(p, "io_directory")) {
		fail("stress io_directory must be an absolute path")
	}
	return nil
}

func RunStressWorker(ctx context.Context, manifest Object, nativeRunner, database, runID string, retain bool, out io.Writer) (err error) {
	defer recoverError(&err)
	if e := ValidateStressWorkerManifest(manifest); e != nil {
		return e
	}
	if !entityid.Valid(runID) {
		fail("stress worker requires the current qualification run ID")
	}
	p := sub(manifest, "pressure")
	cgroup, e := AssertPressureCgroup(p, nativeRunner, database)
	if e != nil {
		return e
	}

