func FromEnvironment() *Notifier {
	notifier := New(os.Getenv("NOTIFY_SOCKET"), os.Getenv("WATCHDOG_USEC"), os.Getenv("WATCHDOG_PID"), os.Getpid())
	for _, name := range []string{"NOTIFY_SOCKET", "WATCHDOG_USEC", "WATCHDOG_PID"} {
		_ = os.Unsetenv(name)
	}
	return notifier
}

// New builds a notifier from explicit environment values.
func New(socket, watchdogUSec, watchdogPID string, pid int) *Notifier {
	notifier := &Notifier{}
	if strings.HasPrefix(socket, "/") || strings.HasPrefix(socket, "@") {
		notifier.socket = socket
	}
	if usec, err := strconv.ParseUint(watchdogUSec, 10, 63); err == nil && usec > 0 {
		owner, pidErr := strconv.Atoi(watchdogPID)
		if watchdogPID == "" || pidErr == nil && owner == pid {
			notifier.watchdog = time.Duration(usec) * time.Microsecond / 2
		}
	}
	return notifier
}

// Enabled reports whether a notification socket is configured.
func (n *Notifier) Enabled() bool { return n != nil && n.socket != "" }

// WatchdogInterval is how often WATCHDOG=1 must be sent, or zero.
func (n *Notifier) WatchdogInterval() time.Duration {
	if n == nil || n.socket == "" {
		return 0
	}
	return n.watchdog
}

// Notify sends one state message such as "READY=1".
func (n *Notifier) Notify(state string) error {
	if !n.Enabled() {
		return nil
	}
	if state == "" || strings.ContainsRune(state, 0) {
		return errors.New("invalid service notification")
	}
	address := &net.UnixAddr{Name: n.socket, Net: "unixgram"}
	if strings.HasPrefix(n.socket, "@") {
		address.Name = "\x00" + n.socket[1:]
	}
	conn, err := net.DialUnix("unixgram", nil, address)
	if err != nil {
		return err
	}
	defer conn.Close()
	_ = conn.SetWriteDeadline(time.Now().Add(time.Second))
	_, err = conn.Write([]byte(state))
	return err
}

// Ready reports that the service finished starting.
func (n *Notifier) Ready(status string) error {
	message := "READY=1"
	if status != "" {
		message += "\nSTATUS=" + strings.ReplaceAll(status, "\n", " ")
	}
	return n.Notify(message)
}

// Stopping reports that the service began an orderly shutdown.
func (n *Notifier) Stopping() error { return n.Notify("STOPPING=1") }

// ExtendStart asks systemd for extension more time to finish starting
// (EXTEND_TIMEOUT_USEC), counted from now.
func (n *Notifier) ExtendStart(extension time.Duration) error {
	return n.Notify("EXTEND_TIMEOUT_USEC=" + strconv.FormatInt(extension.Microseconds(), 10))
}

// KeepStarting sends ExtendStart(extension) at once and then every interval
// until the returned stop is called or ctx ends. It is for a deliberate,
// unbounded pre-READY wait (such as offline restart admission riding out an
// OCI outage) that must not be killed by TimeoutStartSec. stop waits for the
// sender to exit.
func (n *Notifier) KeepStarting(ctx context.Context, interval, extension time.Duration) (stop func()) {
	if !n.Enabled() || interval <= 0 || extension <= interval {
		return func() {}
	}
	ctx, cancel := context.WithCancel(ctx)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			_ = n.ExtendStart(extension)
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
			}
		}
	}()
	return func() {
		cancel()
		<-done
	}
}

// RunWatchdog sends WATCHDOG=1 every interval while healthy returns true
// and stops when ctx ends. An unhealthy service stops sending, so systemd's
// WatchdogSec= restarts it; it never reports a failure itself.
func (n *Notifier) RunWatchdog(ctx context.Context, healthy func() bool) {
	interval := n.WatchdogInterval()
	if interval <= 0 {
		return
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		if healthy == nil || healthy() {
			_ = n.Notify("WATCHDOG=1")
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

// cell is a fake cell: each seat's desired generation, the state its host
// reports at that generation, and its load balancer backend.
type cell struct {
	t        *testing.T
	now      time.Time
	desired  map[string]uint64
	state    map[string]string
	backends map[string]Backend
	members  []Member
	wakes    int
	// withdrawn seats have a withdrawn desired.
	withdrawn map[string]bool
}

func newCell(t *testing.T) *cell {
	return &cell{t: t, now: time.Date(2026, 10, 6, 12, 0, 0, 0, time.UTC),
		desired:  map[string]uint64{"gru-1-db-1": 1, "gru-1-db-2": 1},
		state:    map[string]string{"gru-1-db-1": "running", "gru-1-db-2": "running"},
		backends: map[string]Backend{"10.251.0.21:9465": {Healthy: true}, "10.251.0.22:9465": {Healthy: true}},
		members: []Member{{Node: "gru-1-db-1", Backend: "10.251.0.21:9465", Group: "terrabase"},
			{Node: "gru-1-db-2", Backend: "10.251.0.22:9465", Group: "terrabase"}}}
}

func (c *cell) ListDesired(_ context.Context, role string) ([]host.Desired, error) {
	var out []host.Desired
	for node, generation := range c.desired {
		out = append(out, host.Desired{Node: node, Role: role, Digest: "d", Generation: generation, Withdrawn: c.withdrawn[node]})
	}
	return out, nil
}

func (c *cell) ListHosts(context.Context) ([]host.HostStatus, error) {
	var out []host.HostStatus
	for node, state := range c.state {
		out = append(out, host.HostStatus{Reports: []host.Report{{Node: node, Role: terrabase.Role, Digest: "d",
			Generation: c.desired[node], State: state, ObservedAt: c.now}}})
	}
	return out, nil
}

func (c *cell) controller(store *Store, fence authority.Fencer) *Controller {
	return &Controller{Store: store, Fencer: fence, Hosts: c,
		Seats:    func() ([]Member, error) { return c.members, nil },
		Backends: func(context.Context) (map[string]Backend, error) { return c.backends, nil },
		Now:      func() time.Time { return c.now }, Wake: func() { c.wakes++ }}
}

// release moves every seat to generation; their hosts wait for a permit.
func (c *cell) release(generation uint64) {
	for node := range c.desired {
		c.desired[node], c.state[node] = generation, "waiting"
	}
}

func (c *cell) tick(controller *Controller) {
	c.t.Helper()
	if err := controller.Tick(c.t.Context()); err != nil {
		c.t.Fatal(err)
	}
}

// expect checks which seats are drained and which may restart into their
// desired generation.
func (c *cell) expect(store *Store, drained []string, permitted []string) {
	c.t.Helper()
	got, err := store.Drained(c.t.Context())
	if err != nil {
		c.t.Fatal(err)
	}
	if len(got) != len(drained) {
		c.t.Fatalf("drained %v, want %v", got, drained)
	}
	for _, node := range drained {
		if !got[node] {
			c.t.Fatalf("drained %v, want %v", got, drained)
		}
	}
	for _, member := range c.members {
		want := false
		for _, node := range permitted {
			want = want || node == member.Node
		}
		granted, err := store.Granted(c.t.Context(), member.Node, host.Desired{Role: terrabase.Role, Generation: c.desired[member.Node]})
		if err != nil || granted != want {
			c.t.Fatalf("%s permitted=%v err=%v, want %v", member.Node, granted, err, want)
		}
	}
}

